<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Check, LockKeyhole, RefreshCcw, X } from 'lucide-vue-next'
import { api } from '../../api'
import StatusPill from '../../components/StatusPill.vue'
import type { Episode, Project, Scene, Shot } from '../../types'
const props = defineProps<{ project: Project; canReview: boolean; canEdit: boolean; eventRevision: number }>()
const shots = ref<Shot[]>([]); const selected = ref<Shot | null>(null); const imageUrl = ref(''); const videoUrl = ref(''); const audioUrl = ref(''); const error = ref(''); const notice = ref(''); const reviewReason = ref('')
const pending = computed(() => shots.value.filter(s => ['REVIEW_REQUIRED','APPROVED'].includes(s.status)))
const languageBlocked = computed(() => selected.value?.inspection_json?.checks?.visible_text_language === 'FAIL')
async function load() { const episodes = await api.get<Episode[]>(`/projects/${props.project.id}/episodes`); const all:Shot[] = []; for (const episode of episodes) { const scenes = await api.get<Scene[]>(`/projects/${props.project.id}/episodes/${episode.id}/scenes`); for (const scene of scenes) all.push(...await api.get<Shot[]>(`/projects/${props.project.id}/scenes/${scene.id}/shots`)) } shots.value = all; if (selected.value) selected.value = all.find(s => s.id === selected.value?.id) || null }
function revokeMedia() { for (const url of [imageUrl.value, videoUrl.value, audioUrl.value]) if (url) URL.revokeObjectURL(url); imageUrl.value = ''; videoUrl.value = ''; audioUrl.value = '' }
async function selectShot(shot: Shot) {
  selected.value = shot
  reviewReason.value = ''
  revokeMedia()
  const root = `/projects/${props.project.id}/assets`
  const [image, video, audio] = await Promise.all([
    shot.current_image_asset_id ? api.blob(`${root}/${shot.current_image_asset_id}/content`) : Promise.resolve(''),
    shot.current_video_asset_id ? api.blob(`${root}/${shot.current_video_asset_id}/content`) : Promise.resolve(''),
    shot.current_audio_asset_id ? api.blob(`${root}/${shot.current_audio_asset_id}/content`) : Promise.resolve(''),
  ])
  imageUrl.value = image
  videoUrl.value = video
  audioUrl.value = audio
}
async function transition(target: string) { if (!selected.value) return; try { await api.post(`/projects/${props.project.id}/shots/${selected.value.id}/transition`, { expected_version: selected.value.version, target, review_reason: target === 'APPROVED' ? reviewReason.value : undefined }); notice.value = `审核结果：${target}`; reviewReason.value = ''; await load() } catch (cause) { error.value = (cause as Error).message } }
watch(() => props.eventRevision, load); onMounted(load); onBeforeUnmount(revokeMedia)
</script>
<template>
  <div class="section-head"><div><div class="section-kicker">Human Review</div><h1>镜头审核</h1><p>生成输出需经人工确认，正式批准后才可进入成片时间线。</p></div><button class="btn" @click="load"><RefreshCcw :size="15" />刷新</button></div><div v-if="error" class="error" style="margin-bottom:16px">{{ error }}</div><div v-if="notice" class="notice" style="margin-bottom:16px">{{ notice }}</div>
  <div class="split"><section class="panel panel-pad"><div class="between"><h2>待处理镜头</h2><span class="status">{{ pending.length }}</span></div><div v-if="pending.length" class="list"><button v-for="shot in pending" :key="shot.id" class="list-row" style="text-align:left;color:inherit" @click="selectShot(shot)"><div><strong>Shot {{ String(shot.shot_no).padStart(2,'0') }} · {{ shot.description.slice(0,45) }}</strong><br><small>{{ shot.duration }} 秒 · {{ shot.dialogue || '无对白' }}</small></div><StatusPill :status="shot.status" /></button></div><div v-else class="empty"><div><strong>暂无待审镜头</strong><p>完成生成后，镜头会进入人工审核。</p></div></div></section><aside class="panel panel-pad"><h2>{{ selected ? `Shot ${selected.shot_no}` : '选择镜头' }}</h2><template v-if="selected"><div class="shot-thumb" style="height:auto;aspect-ratio:16/9;border-radius:12px"><img v-if="imageUrl" :src="imageUrl" alt="待审镜头图像" /></div><div v-if="videoUrl" class="video-frame" style="margin-top:12px"><video :src="videoUrl" controls preload="metadata"></video></div><audio v-if="audioUrl" :src="audioUrl" controls preload="metadata" style="width:100%;margin-top:12px"></audio><p class="story-text" style="margin-top:15px">{{ selected.description }}</p><p class="muted" style="font-size:12px">对白：{{ selected.dialogue || '无' }}</p><div class="divider"></div><div class="mini-label">素材核对</div><div class="run-node">图像：{{ selected.current_image_asset_id ? '已生成' : '未生成' }}</div><div class="run-node">视频：{{ selected.current_video_asset_id ? '可播放复核' : '未生成' }}</div><div class="run-node">配音：{{ selected.current_audio_asset_id ? '可播放复核' : '未生成' }}</div><div class="divider"></div><div class="mini-label">Inspector</div><template v-if="selected.inspection_json"><div class="run-node">{{ selected.inspection_json.status }} · {{ selected.inspection_json.method }} · 分数 {{ selected.inspection_json.score.toFixed(2) }}</div><div v-for="(value, key) in selected.inspection_json.checks" :key="key" class="run-node">{{ key }}：{{ value }}</div><p v-for="issue in selected.inspection_json.issues" :key="issue" class="muted" style="font-size:12px">{{ issue }}</p></template><div v-else class="run-node">等待生成与检查</div><div v-if="languageBlocked" class="error" style="margin-top:16px">检测到非中文可见文字，必须重新生成素材，不能人工强制通过。</div><div v-if="canReview && !languageBlocked && ['REVIEW_REQUIRED', 'APPROVED'].includes(selected.status) && selected.inspection_json?.status === 'FAIL' && !selected.inspection_json.review_override" class="field" style="margin-top:16px"><label for="review-reason">检查失败时的人工通过理由</label><textarea id="review-reason" v-model="reviewReason" maxlength="500" rows="2" placeholder="说明人工复核依据；也可直接驳回并重生成"></textarea></div><div v-if="canReview" class="toolbar" style="margin-top:20px"><button v-if="selected.status === 'REVIEW_REQUIRED' && selected.current_video_asset_id && !languageBlocked" class="btn btn-primary" :disabled="selected.inspection_json?.status === 'FAIL' && !reviewReason.trim()" @click="transition('APPROVED')"><Check :size="15" />通过</button><button v-if="selected.status === 'REVIEW_REQUIRED'" class="btn btn-danger" @click="transition('REJECTED')"><X :size="15" />驳回</button><button v-if="selected.status === 'APPROVED' && !languageBlocked && selected.inspection_json?.status === 'FAIL' && !selected.inspection_json.review_override" class="btn btn-primary" :disabled="!reviewReason.trim()" @click="transition('APPROVED')"><Check :size="15" />确认复检</button><button v-if="selected.status === 'APPROVED' && (selected.inspection_json?.status !== 'FAIL' || selected.inspection_json.review_override?.video_asset_id === selected.current_video_asset_id)" class="btn" @click="transition('LOCKED')"><LockKeyhole :size="15" />锁定</button></div></template><div v-else class="empty"><div><strong>等待选择</strong><p>查看素材、对白与状态后给出审核结果。</p></div></div></aside></div>
</template>
